def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        if i == len(line):
            # End of line - add the last field (which may be empty)
            fields.append('')
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote and skip both
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i == len(line):
                            # End of line
                            fields.append(field)
                            break
                        elif line[i] == ',':
                            # Comma follows - add field and move past comma
                            fields.append(field)
                            i += 1
                        else:
                            # Invalid character after closing quote
                            return None
                else:
                    field += line[i]
                    i += 1
            else:
                # Loop ended without finding closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote in unquoted field is malformed
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line):
                # Move past the comma
                i += 1
            else:
                # End of line
                break

    return fields

